using System.Data.SqlClient;

#region "FormPlugin"
public class FormPlugin : System.MarshalByRefObject, JiwaFinancials.Jiwa.JiwaApplication.IJiwaFormPlugin
{

    public override object InitializeLifetimeService()
    {
        // returning null here will prevent the lease manager
        // from deleting the Object.
        return null;
    }

    public void SetupBeforeHandlers(JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm JiwaForm, JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
    }

    public void Setup(JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm JiwaForm, JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
        if (JiwaForm is JiwaFinancials.Jiwa.JiwaLandedCostUI.Shipment.Shipment)
        {
            JiwaFinancials.Jiwa.JiwaLandedCostUI.Shipment.Shipment shipmentForm = (JiwaFinancials.Jiwa.JiwaLandedCostUI.Shipment.Shipment)JiwaForm;

            Infragistics.Win.UltraWinToolbars.RibbonGroup group = shipmentForm.UltraToolbarsManager1.Ribbon.Tabs["Main"].Groups["Actions"];
            Infragistics.Win.UltraWinToolbars.ButtonTool reOpenShipmentTool = new Infragistics.Win.UltraWinToolbars.ButtonTool("Re-Open Shipment");
            reOpenShipmentTool.SharedProps.Caption = "Re-Open Shipment";
            shipmentForm.UltraToolbarsManager1.Tools.Add(reOpenShipmentTool);
            group.Tools.AddTool("Re-Open Shipment");
            group.Tools["Re-Open Shipment"].InstanceProps.MinimumSizeOnRibbon = Infragistics.Win.UltraWinToolbars.RibbonToolSize.Normal;

            shipmentForm.UltraToolbarsManager1.ToolClick += delegate (object sender, Infragistics.Win.UltraWinToolbars.ToolClickEventArgs e)
            {
                if (e.Tool.Key == "Re-Open Shipment")
                {
                    string sqlCommandText = @"UPDATE SH_Main SET Status = 1 WHERE ShipmentID = @ShipmentID";
                    var db = shipmentForm.Manager.Database;
                    using (SqlCommand sqlCommand = new SqlCommand(sqlCommandText, db.SQLConnection, db.SQLTransaction))
                    {
                        sqlCommand.Parameters.AddWithValue("@ShipmentID", shipmentForm.Shipment.RecID);
                        if (sqlCommand.ExecuteNonQuery() > 0)
                        {
                            shipmentForm.Shipment.Read(shipmentForm.Shipment.RecID);
                        }
                    }
                }
            };

            shipmentForm.Shipment.PropertyChanged += delegate (object sender, System.ComponentModel.PropertyChangedEventArgs e)
            {
                shipmentForm.UltraToolbarsManager1.Tools["Re-Open Shipment"].SharedProps.Enabled = !shipmentForm.Shipment.ChangeFlag && shipmentForm.Shipment.Status == JiwaFinancials.Jiwa.JiwaLandedCost.Shipment.Shipment.StatusType.Closed;
                if (shipmentForm.UltraToolbarsManager1.Tools["Re-Open Shipment"].SharedProps.Enabled)
                {
                    shipmentForm.SetPermissions();
                }
            };

            shipmentForm.Shipment.CopyEnd += delegate (object sender, System.EventArgs e)
            {
                shipmentForm.UltraToolbarsManager1.Tools["Re-Open Shipment"].SharedProps.Enabled = !shipmentForm.Shipment.ChangeFlag && shipmentForm.Shipment.Status == JiwaFinancials.Jiwa.JiwaLandedCost.Shipment.Shipment.StatusType.Closed;
                if (shipmentForm.UltraToolbarsManager1.Tools["Re-Open Shipment"].SharedProps.Enabled)
                {
                    shipmentForm.SetPermissions();
                }
            };

            shipmentForm.Shipment.CreateEnd += delegate (object sender, System.EventArgs e)
            {
                shipmentForm.UltraToolbarsManager1.Tools["Re-Open Shipment"].SharedProps.Enabled = !shipmentForm.Shipment.ChangeFlag && shipmentForm.Shipment.Status == JiwaFinancials.Jiwa.JiwaLandedCost.Shipment.Shipment.StatusType.Closed;
                if (shipmentForm.UltraToolbarsManager1.Tools["Re-Open Shipment"].SharedProps.Enabled)
                {
                    shipmentForm.SetPermissions();
                }
            };

            shipmentForm.Shipment.ReadEnd += delegate (object sender, System.EventArgs e)
            {
                shipmentForm.UltraToolbarsManager1.Tools["Re-Open Shipment"].SharedProps.Enabled = !shipmentForm.Shipment.ChangeFlag && shipmentForm.Shipment.Status == JiwaFinancials.Jiwa.JiwaLandedCost.Shipment.Shipment.StatusType.Closed;
                if (shipmentForm.UltraToolbarsManager1.Tools["Re-Open Shipment"].SharedProps.Enabled)
                {
                    shipmentForm.SetPermissions();
                }
            };
        }
    }
}
#endregion

